1	// ── SAP KIT RUNTIME v3 — paste once at the top of every build use_figma call ──
2	// Needs: const KIT = {...}  (generate with: node build/kit.js pack <names...>)
3	// API:  await I('Button', {Type:'Primary', Text:'Save', 'Icon Left':true, Icon:'add'})  → instance
4	//       await T('Hello', 'Header/H3', 'sapTitleColor')   → text node, SAP text style + colour variable bound
5	//       await fill(node, 'sapBackgroundColor') · await stroke(node, 'sapList_BorderColor', {b:1})
6	//       await space(frame, {p:'sapContent_Space_M', gap:8}) — numbers or FLOAT variable names
7	//       AL('VERTICAL', {name, gap, p:[t,r,b,l]}) → auto-layout frame · put(parent, child, 'FILL'|'HUG')
8	//       sub(inst, 'Layer name') → nested instance (to set its props with setP)
9	// Every unknown prop / value / key is pushed to WARN — return WARN from the build. Never silent.
10	const WARN = [], _cache = {};
