23	  for (const k of Object.keys(defs)) byNorm[_norm(k)] = k;
24	  const variants = {}, rest = {};
25	  for (const [name, val] of Object.entries(props)) {
26	    const real = defs[name] ? name : byNorm[_norm(name)];
27	    if (!real) { WARN.push(`${inst.name}: no prop "${name}" (has: ${Object.keys(defs).map(_norm).join(', ')})`); continue; }
28	    const d = defs[real];
29	    if (d.type === 'VARIANT') {
30	      const opts = inst.mainComponent.parent && inst.mainComponent.parent.type === 'COMPONENT_SET'
31	        ? inst.mainComponent.parent.componentPropertyDefinitions[real].variantOptions : [];
32	      const v = String(val), hit = opts.find(o => o.toLowerCase() === v.toLowerCase());
33	      if (!hit) { WARN.push(`${inst.name}.${real}: "${v}" not in [${opts.join(', ')}]`); continue; }
34	      variants[real] = hit;
35	    } else if (d.type === 'INSTANCE_SWAP') {
36	      const key = /^[0-9a-f]{40}$/.test(val) ? val : _k('i', val); if (!key) continue;
37	      rest[real] = (await _imp('c', key)).id;
38	    } else rest[real] = d.type === 'BOOLEAN' ? !!val : String(val);
39	  }
40	  if (Object.keys(variants).length) inst.setProperties(variants);   // variants first: they can reset other props
41	  if (Object.keys(rest).length) inst.setProperties(rest);
42	  return inst;
43	}
44	async function I(name, props = {}, layerName) {
45	  const key = _k('c', name); if (!key) return null;
46	  const n = await _imp('c', key);
47	  const inst = (n.type === 'COMPONENT_SET' ? n.defaultVariant : n).createInstance();
48	  if (layerName) inst.name = layerName;
49	  return setP(inst, props);
50	}
51	function sub(inst, layerName) { return inst.findOne(n => n.type === 'INSTANCE' && n.name === layerName); }
52	async function _paint(varName) { const key = _k('v', varName); if (!key) return null;
53	  const v = await _imp('v', key); return figma.variables.setBoundVariableForPaint({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', v); }
54	async function fill(node, varName) { const p = await _paint(varName); if (p) node.fills = [p]; return node; }
55	async function stroke(node, varName, w = { a: 1 }) {
56	  const p = await _paint(varName); if (!p) return node; node.strokes = [p]; node.strokeAlign = 'INSIDE';
57	  if (w.a) node.strokeWeight = w.a; else Object.assign(node, { strokeTopWeight: w.t || 0, strokeRightWeight: w.r || 0, strokeBottomWeight: w.b || 0, strokeLeftWeight: w.l || 0 });
