94	const _AL = { M: 'MIN', C: 'CENTER', X: 'MAX', S: 'SPACE_BETWEEN' };
95	const _ok = t => typeof t === 'string' && !t.startsWith('RAW');
96	let _made = 0;
97	async function _icon(name, colour) {
98	  const key = _k('i', name); if (!key) return null;
99	  const c = await _imp('c', key);
100	  const inst = (c.type === 'COMPONENT_SET' ? c.defaultVariant : c).createInstance();
101	  inst.name = name;
102	  if (colour) for (const v of inst.findAll(n => n.type === 'VECTOR' || n.type === 'BOOLEAN_OPERATION')) if (v.fills && v.fills.length) await fill(v, colour);
103	  return inst;
104	}
105	function _raw(node, t, stroke) {                         // an unbound colour: keep it visible, report it
106	  const h = t.slice(4), c = { r: parseInt(h.slice(0, 2), 16) / 255, g: parseInt(h.slice(2, 4), 16) / 255, b: parseInt(h.slice(4, 6), 16) / 255 };
107	  node[stroke ? 'strokes' : 'fills'] = [{ type: ['SOLID'][0], color: c }];
108	  WARN.push(`${node.name}: raw colour ${t.slice(3)} — bind a SAP token`);
109	}
110	async function _paintNode(node, o) {
111	  if (o.img) { try { node.fills = [{ type: 'IMAGE', imageHash: o.img, scaleMode: 'FILL' }]; } catch (e) { node.fills = []; WARN.push(`${o.n}: image not in this file — upload the logo crop`); } }
112	  else if (_ok(o.bg)) await fill(node, o.bg); else if (o.bg) _raw(node, o.bg); else if ('fills' in node) node.fills = [];
113	  if (o.bc) {
114	    if (_ok(o.bc)) await stroke(node, o.bc, Array.isArray(o.bw) ? { t: o.bw[0], r: o.bw[1], b: o.bw[2], l: o.bw[3] } : { a: o.bw || 1 });
115	    else _raw(node, o.bc, true);
116	    node.strokeAlign = 'INSIDE';
117	  }
118	  if (o.r && 'cornerRadius' in node) node.cornerRadius = o.r;
119	}
120	// sizing letter per axis: X fixed, H hug, F fill. Old trees wrote F for fixed too → fill only when it spans the parent's free space.
121	let _EXPLICIT = false;                                  // tree.sz === 'x': F always means FILL
122	function _axis(o, par, i) {
123	  const L = (o.s || 'XX')[i];
124	  if (L !== 'F') return L === 'H' ? 'HUG' : 'FIXED';
125	  if (_EXPLICIT) return 'FILL';
126	  if (!par || !par.d) return 'FIXED';
127	  const p = Array.isArray(par.p) ? par.p : [par.p || 0, par.p || 0, par.p || 0, par.p || 0];
128	  const along = (par.d === 'H') === (i === 0), dim = i === 0 ? 'w' : 'h';
129	  if (!along) { const free = i === 0 ? par.w - p[1] - p[3] : par.h - p[0] - p[2]; return Math.abs(o[dim] - free) <= 1 ? 'FILL' : 'FIXED'; }
