139	    try { n[key] = m; } catch (e) { try { n[key] = m = 'FIXED'; } catch (_) {} }
140	    // a FIXED instance keeps its default size unless told (Select button stayed 67 wide instead of 145)
141	    const want = i === 0 ? o.w : o.h, have = i === 0 ? n.width : n.height;
142	    if (m === 'FIXED' && want && Math.abs(have - want) > 0.5 && (n.type !== 'TEXT' || o.wrap))
143	      try { n.resize(i === 0 ? want : n.width, i === 0 ? n.height : want); } catch (_) {}
144	  }
145	}
146	async function NODE(o, parent, par) {
147	  let n;
148	  if (o.k === 't') {
149	    n = await T(o.t, o.st, _ok(o.bg) ? o.bg : null, { name: o.n });
150	    if (o.bg && !_ok(o.bg)) _raw(n, o.bg);
151	    if (o.ta) n.textAlignHorizontal = { C: 'CENTER', R: 'RIGHT', J: 'JUSTIFIED' }[o.ta];
152	    if (o.wrap) { n.textAutoResize = 'HEIGHT'; n.resize(o.w, n.height); }
153	  } else if (o.k === 'i') {
154	    n = await I(o.cp, o.pr || {}, o.n); if (!n) return null;
155	    for (const [nm, ch] of Object.entries(o.tx || {})) {           // text typed inside the instance
156	      const t = n.findOne(x => x.type === 'TEXT' && x.name === nm);
157	      if (!t) { WARN.push(`${o.n}: no inner text "${nm}"`); continue; }
158	      for (const f of t.characters.length ? t.getRangeAllFontNames(0, t.characters.length) : [t.fontName]) await figma.loadFontAsync(f);
159	      t.characters = String(ch);
160	    }
161	  } else if (o.k === 'ic') {
162	    n = await _icon(o.ic, _ok(o.bg) ? o.bg : null); if (!n) return null;
163	    n.name = o.n;
164	    if (o.w && Math.abs(n.width - o.w) > 0.5) n.rescale(o.w / n.width);   // rescale keeps the icon's shape; resize distorts it
165	  } else if (o.k === 'r') {
166	    n = o.el ? figma.createEllipse() : figma.createRectangle(); n.name = o.n;
167	    n.resize(Math.max(0.01, o.w), Math.max(0.01, o.h)); await _paintNode(n, o);
168	  } else if (o.k === 'v') {
169	    n = figma.createNodeFromSvg(o.svg); n.name = o.n; n.fills = [];
170	    const t = o.bg || o.bc;
171	    for (const v of n.findAll(x => x.type === 'VECTOR')) { if (_ok(t)) { if (v.fills.length) await fill(v, t); if (v.strokes.length) await stroke(v, t); } else if (t) _raw(v, t); }
172	  } else {
173	    n = o.d ? figma.createAutoLayout(o.d === 'H' ? 'HORIZONTAL' : 'VERTICAL') : figma.createFrame();
174	    n.name = o.n;
175	    if (o.d) {
176	      n.itemSpacing = o.g || 0;
177	      const p = Array.isArray(o.p) ? o.p : [o.p || 0, o.p || 0, o.p || 0, o.p || 0];
178	      [n.paddingTop, n.paddingRight, n.paddingBottom, n.paddingLeft] = p;
179	      const a = o.a || 'MM'; n.primaryAxisAlignItems = _AL[a[0]]; n.counterAxisAlignItems = a[1] === 'S' ? 'MIN' : _AL[a[1]];
180	      n.strokesIncludedInLayout = false;
181	    }
182	    n.resize(Math.max(0.01, o.w), Math.max(0.01, o.h));
183	    await _paintNode(n, o);
184	    n.clipsContent = !!o.clip;
185	  }
186	  _made++;
187	  if (parent) {
188	    parent.appendChild(n);
189	    if (o.abs && par && par.d) n.layoutPositioning = 'ABSOLUTE';
190	    // an SVG's box can be bigger than the vector's (a 0-high line exports 6 high) → centre it on the vector's box
191	    if (o.xy) { n.x = o.xy[0] + (o.k === 'v' ? (o.w - n.width) / 2 : 0); n.y = o.xy[1] + (o.k === 'v' ? (o.h - n.height) / 2 : 0); }
192	    _size(n, o, par);
193	  }
194	  if (o.c && !o.k) for (const ch of o.c) await NODE(ch, n, o);
195	  return n;
196	}
197	async function BUILD_TREE(tr) {
198	  _EXPLICIT = tr.sz === 'x';
199	  const root = await NODE(tr, null, null);
200	  let maxX = 0; for (const k of figma.currentPage.children) if (k !== root) maxX = Math.max(maxX, k.x + k.width);

