}
async function I(name, props = {}, layerName) {
  const key = _k('c', name); if (!key) return null;
  const n = await _imp('c', key);
  const inst = (n.type === 'COMPONENT_SET' ? n.defaultVariant : n).createInstance();
  if (layerName) inst.name = layerName;
