// Check arrow nodes inside Flight card 1
const root = figma.currentPage.findOne(n => n.id === '451:9507');
const arrows = root.findAll(n => n.name === 'Arrow line');
return arrows.map(a => ({
  name: a.name, type: a.type, w: Math.round(a.width), h: Math.round(a.height),
  x: Math.round(a.absoluteX), y: Math.round(a.absoluteY),
  visible: a.visible, fills: a.fills ? a.fills.length : 'n/a',
  parent: a.parent ? a.parent.name : 'n/a'
}));

// Check arrow nodes
const root = figma.currentPage.findOne(n => n.id === '451:9507');
const arrows = root.findAll(n => n.name === 'Arrow line');
return arrows.slice(0, 4).map(a => ({
  name: a.name, type: a.type, w: Math.round(a.width), h: Math.round(a.height),
  visible: a.visible, fillsLen: a.fills ? a.fills.length : 'n/a',
  strokesLen: a.strokes ? a.strokes.length : 'n/a',
  parent: a.parent ? a.parent.name : 'n/a',
  grandparent: a.parent && a.parent.parent ? a.parent.parent.name : 'n/a'
}));

// Inspect inside an Arrow line node
const root = figma.currentPage.findOne(n => n.id === '451:9507');
const arrowFrame = root.findOne(n => n.name === 'Arrow line');
const children = arrowFrame.findAll();
return {
  frameW: Math.round(arrowFrame.width), frameH: Math.round(arrowFrame.height),
  children: children.slice(0, 10).map(c => ({
    name: c.name, type: c.type, w: Math.round(c.width), h: Math.round(c.height),
    fillsLen: c.fills ? c.fills.length : 'n/a',
    strokesLen: c.strokes ? c.strokes.length : 'n/a',
    fillBound: c.fills && c.fills[0] ? (c.fills[0].boundVariables ? Object.keys(c.fills[0].boundVariables) : 'no vars') : 'n/a'
  }))
};

// Check what color sapTile_Interactive_BorderColor resolves to
const root = figma.currentPage.findOne(n => n.id === '451:9507');
const arrowFrame = root.findOne(n => n.name === 'Arrow line');
const vec = arrowFrame.findOne(n => n.type === 'VECTOR');
if (!vec || !vec.fills.length) return 'no fills';
const fill = vec.fills[0];
const bv = fill.boundVariables;
if (!bv || !bv.color) return { fill, note: 'no boundVariable' };
// Get the variable
const varId = bv.color.id;
const variable = figma.variables.getVariableById(varId);
if (!variable) return 'variable not found';
return { name: variable.name, resolvedType: variable.resolvedType, valuesByMode: variable.valuesByMode };

// Check pin circle stroke colors
const root = figma.currentPage.findOne(n => n.id === '451:9507');
const pins = root.findAll(n => n.name === 'Pin');
return pins.slice(0, 2).map(p => ({
  name: p.name, strokes: p.strokes ? p.strokes.length : 0,
  strokeVar: p.strokes && p.strokes[0] && p.strokes[0].boundVariables ? 
    Object.entries(p.strokes[0].boundVariables).map(([k,v]) => `${k}=${v.id}`) : 'none'
}));

// Check pin circle variable ID and "Директен" text styles
const root = figma.currentPage.findOne(n => n.id === '451:9507');

// Check pin variable
const pintNodes = root.findAll(n => n.name === 'Pin');
const pinStrokeVar = pintNodes[0]?.strokes?.[0]?.boundVariables?.color;

// Check "Директен" text nodes
const direktenNodes = root.findAll(n => n.type === 'TEXT' && n.characters === 'Директен');
const dirInfo = direktenNodes.slice(0,2).map(n => ({
  id: n.id, chars: n.characters, fontName: n.fontName,
  textStyleId: n.textStyleId,
  boundVars: n.boundVariables ? Object.keys(n.boundVariables) : []
}));

// Check "14:10" text node
const timeNodes = root.findAll(n => n.type === 'TEXT' && n.characters === '14:10');
const timeInfo = timeNodes.slice(0,1).map(n => ({
  id: n.id, chars: n.characters, fontName: n.fontName, textStyleId: n.textStyleId
}));

return { pinStrokeVar, dirInfo, timeInfo };

