const plan = JSON.parse(fs.readFileSync(planF, 'utf8'));
const tree = JSON.parse(fs.readFileSync(treeF, 'utf8'));
const PASS = 90;
const L = { missing: [], style: [], colour: [], prop: [], density: [], hygiene: [] };
const used = new Set();
