// SAP KIT RUNTIME v3 — minimal patch, no creates
// end SAP KIT RUNTIME
// Fix 1: "До 2 спирки" option label colour → sapTextColor
// Fix 2: Flight card 2 disclaimer text → correct amount

const vars = await figma.variables.getLocalVariablesAsync();
const sapTextColorVar = vars.find(v => v.name === 'sapTextColor');

// Fix "До 2 спирки" label fill
const node1 = await figma.getNodeByIdAsync('451:9553');
if (node1 && sapTextColorVar) {
  node1.fills = [figma.variables.setBoundVariable({ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }, 'color', sapTextColorVar)];
}

// Fix card 2 disclaimer (wrong amount 37,27 → 38,65 — already correct in dump; check actual)
const discNode2 = await figma.getNodeByIdAsync('451:9898');
const currentText = discNode2 ? discNode2.characters : 'not found';

return { 
  fix1: node1 ? 'sapTextColor applied to До 2 спирки' : 'node not found',
  disclaimer2text: currentText
};

// Quick re-check: pull just the disclaimer nodes and До 2 спирки colour
const n1 = await figma.getNodeByIdAsync('451:9553'); // До 2 спирки
const n2 = await figma.getNodeByIdAsync('451:9898'); // card 2 disclaimer

const getVar = async fills => {
  if (!fills || !fills[0] || !fills[0].boundVariables) return 'no var';
  const id = fills[0].boundVariables.color && fills[0].boundVariables.color.id;
  if (!id) return 'RAW';
  const v = await figma.variables.getVariableByIdAsync(id);
  return v ? v.name.split('/').pop() : 'unknown';
};

return {
  optionLabel: { text: n1.characters, fill: await getVar(n1.fills) },
  disclaimer2: { text: n2.characters.slice(0, 60), fill: await getVar(n2.fills) }
};

