// dump-layout.use_figma.js — READ-ONLY dump of approved build for gold tree
const ROOT = '451:9507';
const root = await figma.getNodeByIdAsync(ROOT);
const vc = {}, sc = {};
async function tok(bv) {
  if (!bv || !bv.id) return null;
  if (!(bv.id in vc)) { const v = await figma.variables.getVariableByIdAsync(bv.id); vc[bv.id] = v ? v.name.split('/').pop() : null; }
  return vc[bv.id];
}
async function paintTok(paints) {
  if (!Array.isArray(paints) || !paints.length || paints[0].visible === false) return undefined;
  const p = paints[0];
  if (p.type === 'IMAGE') return { img: p.imageHash };
  if (p.type !== 'SOLID') return undefined;
  const t = await tok(p.boundVariables && p.boundVariables.color);
  if (t) return t;
  const c = p.color, h = x => Math.round(x * 255).toString(16).padStart(2, '0');
  return 'RAW#' + h(c.r) + h(c.g) + h(c.b);
}
const A = { MIN: 'M', CENTER: 'C', MAX: 'X', SPACE_BETWEEN: 'S', BASELINE: 'C' };
const r1 = x => Math.round(x * 10) / 10;
function propsOf(inst) {
  const out = {}, set = inst.mainComponent && inst.mainComponent.parent && inst.mainComponent.parent.type === 'COMPONENT_SET' ? inst.mainComponent.parent : null;
  if (!set) return out;
  for (const [k, v] of Object.entries(inst.componentProperties)) {
    if (v.type !== 'VARIANT') continue;
    const def = set.componentPropertyDefinitions[k];
    if (!def || def.defaultValue === v.value) continue;
    out[k] = v.value;
  }
  return out;
}
async function node(n, depth) {
  if (n.visible === false) return null;
  if (depth > 20) return null;
  const o = { n: n.name };
  if (n.type === 'TEXT') {
    const st = n.textStyleId && typeof n.textStyleId === 'string' ? await figma.getStyleByIdAsync(n.textStyleId) : null;
    const fg = await paintTok(n.fills);
    const obj = { k: 't', t: n.characters };
    if (st) obj.st = st.name; if (fg) obj.bg = fg;
    if (n.textAutoResize !== 'WIDTH_AND_HEIGHT') obj.wrap = 1;
    return { ...o, ...obj };
  }
  if (n.type === 'INSTANCE') {
    const m = await n.getMainComponentAsync();
    const s = m && m.parent && m.parent.type === 'COMPONENT_SET' ? m.parent : m;
    const cp = s ? s.name : '';
    const pr = propsOf(n);
    return { ...o, k: 'i', cp, pr };
  }
  if (n.type === 'VECTOR') {
    const bg = await paintTok(n.fills);
    const bc = n.strokes && n.strokes.length ? await tok(n.strokes[0].boundVariables && n.strokes[0].boundVariables.color) : null;
    return { ...o, k: 'v', ...(bg ? { bg } : {}), ...(bc ? { bc } : {}) };
  }
  if (n.type === 'RECTANGLE') {
    const bg = await paintTok(n.fills);
    return { ...o, k: 'r', ...(bg ? { bg } : {}) };
  }
  const obj = { w: Math.round(n.width), h: Math.round(n.height) };
  if (n.layoutMode && n.layoutMode !== 'NONE') {
    obj.d = n.layoutMode === 'HORIZONTAL' ? 'H' : 'V';
    obj.g = Math.round(n.itemSpacing);
